<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ArrowLeft,ArrowUpRight,Compass,Upload,BookOpen,Radio,KeyRound} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import {validatePlayIntent,type PlayIntent,type PlayDefinition} from './contract'
import {playableTemplates} from './templates'
import {newPlayableIntent,savePlayableIntent,executePlayableIntent,parsePlayablePackage} from './operations'
const store=useLocal(),route=useRoute(),router=useRouter(),busy=ref(false),loaded=ref(false),error=ref(''),intent=ref<Document<PlayIntent>|null>(null),missing=ref(false)
const icons=[BookOpen,Radio,KeyRound];let disposed=false,opening:ReturnType<typeof newPlayableIntent>|null=null,completed=false
function active(vault:typeof store.vault){return !disposed&&vault===store.vault&&!!vault?.unlocked}
async function choose(def:PlayDefinition){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';opening??=newPlayableIntent(def);try{const row=await savePlayableIntent(vault,opening.id,opening.value);if(active(vault)){intent.value=row;await router.replace({path:'/local/new-world',query:{intent:row.id}})}}catch(e){if(active(vault))error.value=(e as Error).message}finally{if(active(vault))busy.value=false}}
async function start(){const vault=store.vault,row=intent.value;if(!vault||!row||busy.value)return;busy.value=true;error.value='';try{if(row.value.status==='ready')await executePlayableIntent(vault,row);if(active(vault)){completed=true;await router.push('/local/play/'+row.value.worldId)}}catch(e){if(active(vault))error.value=(e as Error).message}finally{if(active(vault))busy.value=false}}
async function imported(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||busy.value)return;try{if(file.size>2*1024*1024)throw Error('文游作品包超过 2MB');const text=await file.text();if(disposed)return;await choose(parsePlayablePackage(text))}catch(e){if(!disposed)error.value=(e as Error).message}(event.target as HTMLInputElement).value=''}
async function load(){const vault=store.vault;if(!vault)return;busy.value=true;try{const id=route.query.intent;if(typeof id==='string'){const row=await vault.read<PlayIntent>(id);if(!active(vault))return;if(!row||row.kind!=='settings')missing.value=true;else{validatePlayIntent(row.value,row.id);if(row.value.type!=='create'||row.value.status==='discarded')missing.value=true;else intent.value=row}}}catch(e){if(active(vault))error.value=(e as Error).message}finally{if(active(vault)){loaded.value=true;busy.value=false}}}
onBeforeRouteLeave(()=>{if(busy.value&&loaded.value&&!completed)return false});onMounted(()=>void load());onUnmounted(()=>disposed=true)
</script>
<template><section class="play-create"><RouterLink class="play-back" to="/local/library"><ArrowLeft :size="18"/>书架</RouterLink><div class="final-page-heading"><div><span class="final-eyebrow">A WORLD TO STEP INTO</span><h1>走进另一个故事</h1></div></div><p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="!loaded" role="status">正在打开…</p><div v-else-if="missing" class="final-empty"><Compass :size="32"/><h2>这次创建已失效</h2><RouterLink to="/local/new-world">重新选择作品</RouterLink></div><article v-else-if="intent" class="play-launch"><div class="play-launch-mark"><Compass :size="38"/></div><span class="final-eyebrow">{{intent.value.definition?.layout==='investigation'?'线索与选择':'一段新的旅程'}}</span><h2>{{intent.value.definition?.name}}</h2><p>{{intent.value.definition?.description}}</p><button class="final-primary" :disabled="busy" @click="start">{{busy?'正在保存…':intent.value.status==='completed'?'继续游玩':error?'重试开始':'开始游玩'}}<ArrowUpRight :size="18"/></button></article><template v-else><div class="play-template-grid"><button v-for="(def,i) in playableTemplates" :key="def.name" class="play-template" :disabled="busy||!!opening" @click="choose(def)"><span class="play-template-art" :class="'play-art-'+i"><component :is="icons[i]" :size="54"/><span>{{String(i+1).padStart(2,'0')}}</span></span><span class="play-template-copy"><small>{{['叙事 · 抉择','对话 · 守护','线索 · 解谜'][i]}}</small><strong>{{def.name}}</strong><span>{{def.description}}</span><span class="play-template-enter">选择这个故事<ArrowUpRight :size="18"/></span></span></button></div><div class="play-create-more"><label class="play-import"><Upload :size="18"/>导入文游作品<input type="file" accept="application/json,.json" :disabled="busy||!!opening" @change="imported"></label><RouterLink to="/worlds/new">创建账户互动世界<ArrowUpRight :size="16"/></RouterLink></div><button v-if="opening&&error" class="final-primary" :disabled="busy" @click="choose(opening.value.definition!)">重试保存选择</button></template></section></template>
<style scoped>
.play-create{max-width:1160px;margin:auto}.play-back{display:inline-flex;gap:8px;align-items:center;min-height:44px;color:var(--quiet);margin-bottom:24px}.play-template-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.play-template{padding:0!important;text-align:left!important;display:block!important;overflow:hidden;border:1px solid var(--edge);border-radius:22px;background:var(--panel)!important;color:var(--ink)!important;box-shadow:0 6px 22px #162a2105;transition:transform .2s,box-shadow .2s;min-width:0}.play-template:hover{transform:translateY(-4px);box-shadow:0 16px 36px #162a2110}.play-template-art{position:relative;height:230px;display:grid;place-content:center;overflow:hidden;color:var(--accent);background:radial-gradient(ellipse at 60% 25%,#cadbd180,transparent 65%),var(--wash)}.play-template-art:before,.play-template-art:after{content:'';position:absolute;border:1px solid currentColor;opacity:.16;border-radius:50%;width:280px;height:280px;left:30%;top:45%;pointer-events:none}.play-template-art:after{left:-30%;top:-75%;width:360px;height:360px}.play-template-art>span{position:absolute;bottom:18px;left:22px;font:18px var(--font-reading,serif);opacity:.6}.play-art-1{color:#927a40;background:radial-gradient(ellipse at 20% 20%,#f3e4ba80,transparent 70%),var(--wash)}.play-art-2{color:#896369;background:radial-gradient(ellipse at 70% 30%,#ead3d780,transparent 70%),var(--wash)}.play-template-copy{display:grid;gap:14px;padding:24px}.play-template-copy small,.play-template-copy>span{font-weight:400;color:var(--quiet);line-height:1.6}.play-template-copy strong{font:26px var(--font-reading,serif);color:var(--ink);line-height:1.4}.play-template-enter{display:flex;justify-content:space-between;align-items:center;color:var(--accent)!important;margin-top:12px}.play-create-more{display:flex;flex-wrap:wrap;justify-content:space-between;gap:18px;margin:28px 0}.play-import,.play-create-more>a{display:flex;gap:8px;align-items:center;min-height:48px;padding:12px 16px;border:1px solid var(--edge);border-radius:12px;cursor:pointer;color:var(--quiet)}.play-import{position:relative;overflow:hidden}.play-import input{position:absolute;inset:0;opacity:0;cursor:pointer}.play-launch{max-width:680px;margin:24px auto;padding:48px 32px;display:grid;gap:22px;justify-items:center;text-align:center;background:var(--panel);border:1px solid var(--edge);border-radius:24px}.play-launch h2{font:34px var(--font-reading,serif);margin:0}.play-launch p{color:var(--quiet);line-height:1.8;max-width:400px}.play-launch-mark{width:90px;height:90px;border-radius:50%;background:var(--wash);display:grid;place-content:center;color:var(--accent)}.play-launch button{min-height:48px}.play-create-more a:hover{color:var(--accent)}@media(max-width:850px){.play-template-grid{grid-template-columns:1fr}.play-template{display:grid!important;grid-template-columns:140px minmax(0,1fr)}.play-template-art{height:100%;min-height:230px}.play-template-copy{padding:22px}.play-template-copy strong{font-size:24px}}@media(max-width:430px){.play-template{grid-template-columns:100px minmax(0,1fr)}.play-template-art svg{width:38px}.play-template-copy{padding:20px 16px;gap:10px}.play-template-copy strong{font-size:22px}.play-create-more{flex-direction:column}.play-launch{padding:32px 20px}.play-launch h2{font-size:28px}}@media(prefers-reduced-motion:reduce){.play-template{transition:none}.play-template:hover{transform:none}}
</style>
